#if !defined(__CUDA_ARCH__)
namespace av2enc::inter::adv::tables::detail {

template <typename T>
constexpr bool same_table_entry(const T& a, const T& b) {
  return a == b;
}

template <typename T, std::size_t N>
constexpr bool same_table_entry(const T (&a)[N], const T (&b)[N]) {
  for (std::size_t i = 0; i < N; ++i) {
    if (!same_table_entry(a[i], b[i])) return false;
  }
  return true;
}

constexpr bool advanced_tables_match() {
  if (!same_table_entry(kExtWarpedFiltersDev, kExtWarpedFilters)) return false;
  if (!same_table_entry(kIiWeights1dDev, kIiWeights1d)) return false;
  if (!same_table_entry(kNegDist2BldWeightDev, kNegDist2BldWeight)) return false;
  if (!same_table_entry(kPosDist2BldWeightDev, kPosDist2BldWeight)) return false;
  if (!same_table_entry(kWarpedFiltersDev, kWarpedFilters)) return false;
  if (!same_table_entry(kWedgeAngleDist2IndexDev, kWedgeAngleDist2Index)) return false;
  if (!same_table_entry(kWedgeBitsDev, kWedgeBits)) return false;
  if (!same_table_entry(kWedgeBlockHeightDev, kWedgeBlockHeight)) return false;
  if (!same_table_entry(kWedgeBlockWidthDev, kWedgeBlockWidth)) return false;
  if (!same_table_entry(kWedgeCodebookDev, kWedgeCodebook)) return false;
  if (!same_table_entry(kWedgeCosLutDev, kWedgeCosLut)) return false;
  if (!same_table_entry(kWedgeSinLutDev, kWedgeSinLut)) return false;
  if (kBlock16x16Dev != kBlock16x16) return false;
  if (kBlock64x64Dev != kBlock64x64) return false;
  if (kBlock8x8Dev != kBlock8x8) return false;
  if (kBlockSizesDev != kBlockSizes) return false;
  if (kExtWarpedFilterRowsDev != kExtWarpedFilterRows) return false;
  if (kExtWarpedFilterTapsDev != kExtWarpedFilterTaps) return false;
  if (kNumWedgeDistDev != kNumWedgeDist) return false;
  if (kWarpedFilterRowsDev != kWarpedFilterRows) return false;
  if (kWarpedFilterTapsDev != kWarpedFilterTaps) return false;
  if (kWedgeAnglesDev != kWedgeAngles) return false;
  if (kWedgeBldLutSizeDev != kWedgeBldLutSize) return false;
  if (kWedgeBoundaryTypesDev != kWedgeBoundaryTypes) return false;
  if (kWedgeTypesDev != kWedgeTypes) return false;
  return true;
}

}  // namespace av2enc::inter::adv::tables::detail
static_assert(av2enc::inter::adv::tables::detail::advanced_tables_match(),
              "device advanced-inter tables drifted from the CPU tables");
#endif  // !__CUDA_ARCH__

#endif  // AV2ENC_CUDA_INTER_ADVANCED_TABLES_DEVICE_CUH_
